self.onInit = function() {
    enhanceWanDownlinkActions();
    self.ctx.$scope.mapWidget.onInit();
};

function enhanceWanDownlinkActions() {
    const markers = self.ctx.settings && self.ctx.settings.markers;
    if (!Array.isArray(markers)) {
        return;
    }
    const action = {
        name: "wanDownlink",
        type: "custom",
        customFunction: "let $injector = widgetContext.$scope.$injector;\nlet downlinkDialog = $injector.get(widgetContext.servicesMap.get(\"wanDownlinkDialog\"));\ndownlinkDialog.open({\n  deviceId: entityId.id,\n  deviceName: entityName,\n  origin: \"MAP\"\n}).subscribe();"
    };
    const actionTag = "wanDownlink";
    const appendAction = "\nif (Number(data.activeAlarmCount || 0) > 0) {\n  tooltip += \"<br/><br/><button-act name=\\\"wanDownlink\\\">{i18n:device.wan.send-message}</button-act>\";\n}\nreturn tooltip;";
    markers.forEach(function(marker) {
        const tooltip = marker.tooltip;
        if (!tooltip || !tooltip.show) {
            return;
        }
        if (tooltip.type === "pattern") {
            const originalPattern = tooltip.pattern || "";
            tooltip.type = "function";
            tooltip.patternFunction = {
                type: "JS",
                body: "var tooltip = " + JSON.stringify(originalPattern) + ";" + appendAction,
                modules: {}
            };
            delete tooltip.pattern;
        } else if (tooltip.type === "function" && tooltip.patternFunction
                && !tooltip.patternFunction.body.includes(actionTag)) {
            const originalBody = tooltip.patternFunction.body;
            tooltip.patternFunction.body = "var tooltip = (function(data, dsData, ctx) {\n"
                    + originalBody + "\n})(data, dsData, ctx);" + appendAction;
        }
        tooltip.tagActions = (tooltip.tagActions || []).filter(function(item) {
            return item.name !== action.name;
        });
        tooltip.tagActions.push(action);
    });
}

self.typeParameters = function() {
    return {
        hideDataTab: true,
        hideDataSettings: true,
        previewWidth: "80%",
        embedTitlePanel: true,
        embedActionsPanel: true,
        datasourcesOptional: true,
        additionalWidgetActionTypes: ["placeMapItem"]
    };
};

